import {KANA,LESSONS,BY_ID,SOURCES} from './content.mjs';
import {STORAGE_KEY,freshState,startSession,answer,advance,stats,validateState,dateKey,learnedKana,sessionTitle} from './engine.mjs';
import {createCloudSync} from './cloud-sync.mjs';
import {PRIVATE_APP} from './config.mjs';
import {kanaAudioURL} from './kana-audio.mjs';
import {GENKI_UNITS,GENKI_UNIT_BY_ID,GENKI_QUESTION_BY_ID,GENKI_AUDIO} from './genki-content.mjs';
import {startGenki,answerGenki,advanceGenki} from './genki-engine.mjs';
import {genkiHome,genkiLesson} from './genki-ui.mjs';
import {startDungeon,selectMonster,moveDungeon,attackDungeon,hintDungeon,continueDungeon,descendDungeon} from './dungeon-engine.mjs';
import {dungeonHome,dungeonRun} from './dungeon-ui.mjs';

const paths={cloud:'M6 18a5 5 0 1 1 1-10 6 6 0 0 1 11-1 5 5 0 1 1 1 11H6Zm6-6v8m-3-3 3 3 3-3',sprout:'M12 21v-9m0 3C3 16 2 7 3 4c7-1 10 5 9 11Zm0-4C11 4 18 2 22 4c1 6-4 10-10 7Z',home:'m3 10 9-7 9 7M5 9v12h14V9M9 21v-7h6v7',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',chart:'M4 20V10m8 10V4m8 16v-7',book:'M12 6C8 3 4 3 2 4v15c3-1 6-1 10 2 4-3 7-3 10-2V4c-2-1-6-1-10 2Zm0 0v15',arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',speaker:'m11 4-6 5H2v6h3l6 5V4Zm4 4c3 2 3 6 0 8m3-11c5 4 5 10 0 14',check:'m5 12 4 4L20 5',close:'m6 6 12 12M6 18 18 6',repeat:'m20 7-4-4m4 4H7a4 4 0 0 0-4 4m1 6 4 4m-4-4h13a4 4 0 0 0 4-4',fire:'M12 2c1 6-5 7-5 11 0 3 2 5 5 5s5-2 5-5c0-2-1-4-2-5 0 3-2 3-2 3s2-5-1-9ZM7 8c-4 3-5 6-3 10 3 7 14 6 16-1 1-4-2-8-4-10',star:'m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1 3-6Z',leaf:'M20 3C8 1 1 8 5 16s17 6 15-13ZM5 20 16 9',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',upload:'M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',lock:'M5 10h14v11H5zM8 10V6a4 4 0 0 1 8 0v4'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.leaf}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=document.querySelector('#app');
let state=freshState(),storageWorks=true,view='home',audio=null,toastTimer,playingId=null,cloud;
try{const saved=localStorage.getItem(STORAGE_KEY);if(saved)state=validateState(JSON.parse(saved));}catch(error){storageWorks=false;}
if(state.activeCourse==='dungeon'&&state.dungeon.run)view='dungeon-run';else if(state.activeCourse==='genki'&&state.genki.session)view='genki-lesson';else if(state.session)view='lesson';
if(location.hash==='#dungeon'&&!(state.activeCourse==='dungeon'&&state.dungeon.run))view='dungeon';
let genkiDraft=[],genkiDraftOwner='';
function save(sync=true){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageWorks=true;}catch(error){storageWorks=false;toast('Не удалось сохранить прогресс. Выгрузи его на вкладке «Прогресс».',true);}if(sync)cloud?.noteChange();}
function toast(message,error=false){const el=document.querySelector('#toast');el.textContent=message;el.className=`toast visible ${error?'error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),5500);}
function navLink(id,label,i){return `<button class="nav-item ${view===id?'active':''}" data-action="nav" data-view="${id}" ${view===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${view===id?'<span class="nav-dot"></span>':''}</button>`;}
function shell(body){const s=stats(state);return `<div class="app-shell"><aside class="sidebar"><button class="brand" data-action="nav" data-view="home" aria-label="Кана — уроки"><span class="brand-mark" lang="ja">あ</span><span>Кана</span></button><nav aria-label="Основная навигация">${navLink('home','Уроки','home')}${navLink('practice','Повторение','repeat')}${navLink('dungeon','Подземелье','grid')}${navLink('alphabet','Азбука','grid')}${navLink('progress','Прогресс','chart')}${navLink('sync','Синхронизация','cloud')}</nav><div class="sidebar-bottom">${navLink('sources','Источники','book')}<div class="save-label"><span class="status-dot ${storageWorks?'':'warn'}"></span>${storageWorks?'Сохранено на устройстве':'Сохранение недоступно'}</div></div></aside><div class="main-wrap"><header class="topbar"><span class="breadcrumb">Японский <span>／</span> <strong>${view.startsWith('genki')?'Genki 1':view.startsWith('dungeon')?'Подземелье':'Хирагана'}</strong></span><span class="mobile-brand" lang="ja">あ <span lang="ru">Кана</span></span><div class="top-stats"><span class="streak" title="Дни занятий подряд">${icon('fire')} ${s.streak}</span><span class="xp-pill">${icon('star')} ${state.xp} XP</span>${cloudIndicator()}</div></header><main id="main" tabindex="-1">${body}</main></div><nav class="mobile-nav" aria-label="Навигация на телефоне">${navLink('home','Уроки','home')}${navLink('practice','Повторение','repeat')}${navLink('alphabet','Азбука','grid')}${navLink('progress','Прогресс','chart')}</nav></div>`;}
function lessonCard(l,i){const completed=state.completed.includes(l.id);const next=!completed&&LESSONS.slice(0,i).every(x=>state.completed.includes(x.id));return `<button class="lesson-card ${next?'next':''} ${completed?'complete':''}" data-action="start" data-id="${l.id}"><span class="lesson-symbol" lang="ja">${completed?icon('check'):BY_ID[l.ids[0]].char}</span><span class="lesson-card-copy"><span class="lesson-kicker">УРОК ${String(i+1).padStart(2,'0')} <span>· ${l.ids.length} ЗНАК${l.ids.length===3?'А':'ОВ'}</span></span><strong>${l.label}</strong><span class="kana-preview" lang="ja">${l.ids.map(id=>BY_ID[id].char).join('　')}</span></span><span class="lesson-end">${next?'<span class="next-label">СЛЕДУЮЩИЙ</span>':completed?'<span class="done-label">Пройдено</span>':`<span class="lesson-time">${icon('clock')} ${l.duration} мин</span>`}<span class="lesson-arrow">${icon(next?'arrow':'chevron')}</span></span></button>`;}
function home(){
 const s=stats(state),active=state.session&&!state.session.finished;
 const next=active?LESSONS.find(l=>l.id===state.session.lessonId):LESSONS.find(l=>!state.completed.includes(l.id))||LESSONS[0];
 const nextTitle=active?sessionTitle(state.session.lessonId):next.label;
 const step=active?(state.session.phase==='learn'?`Знак ${state.session.learnIndex+1} / ${state.session.ids.length}`:`Задание ${state.session.index+1} / ${state.session.questions.length}`):`${next.ids.length} знаков · ${next.duration} мин`;
 return shell(`<div class="page-heading compact-heading"><div><h1>Уроки</h1><p>Хирагана · Genki 1</p></div></div><section class="study-summary" aria-label="Прогресс хираганы"><div><strong>${state.completed.length}<small> / 10</small></strong><span>уроков пройдено</span></div><div><strong>${s.mastered}<small> / 46</small></strong><span>знаков закреплено</span></div><div><strong>${s.accuracy}<small>%</small></strong><span>верных ответов</span></div></section><section class="continue-panel"><div class="continue-copy"><span class="eyebrow">${active?'ТЕКУЩИЙ УРОК':'СЛЕДУЮЩИЙ УРОК'}</span><h2>${nextTitle}</h2><span class="muted">${step}</span></div><button class="primary" data-action="${active?'resume':'start'}" data-id="${next?.id||'review'}">${active?'Продолжить':'Начать'}${icon('arrow')}</button></section><button class="practice-banner" data-action="nav" data-view="practice"><span><strong>Закрепить изученное</strong><small>${learnedKana(state).length} знакомых знаков · в любое время</small></span>${icon('repeat')}</button><div class="review-actions"><button class="secondary" data-action="start" data-id="mistakes" ${!state.mistakes.length?'disabled':''}>${icon('repeat')} Ошибки <span class="count">${state.mistakes.length}</span></button><button class="secondary" data-action="start" data-id="review" ${!s.due?'disabled':''}>${icon('clock')} По расписанию <span class="count">${s.due}</span></button></div><button class="genki-course-card" data-action="nav" data-view="genki"><span><strong>Genki 1 — Знакомство</strong><small>28 слов · грамматика · диалоги</small></span><span>${state.genki.completed.length} / 7 ${icon('chevron')}</span></button><button class="genki-course-card dungeon-course-card" data-action="nav" data-view="dungeon"><span><strong>Подземелье хираганы</strong><small>${state.dungeon.run?.status==='explore'?'Продолжить · этаж '+state.dungeon.run.floor+'/3':'3 этажа · монстры-знаки · ввод чтения'}</small></span><span>@ ${icon('chevron')}</span></button><section class="lessons-section compact-lessons"><div class="section-heading"><h2>Хирагана</h2><span class="muted">3–4 минуты каждый</span></div><div class="module-progress" role="progressbar" aria-label="Пройденные уроки" aria-valuemin="0" aria-valuemax="10" aria-valuenow="${state.completed.length}"><span style="width:${state.completed.length*10}%"></span></div><div class="lesson-list">${LESSONS.map(lessonCard).join('')}</div></section>`);
}
function alphabet(){return shell(`<div class="page-heading"><div><h1>Азбука</h1><p>Нажми на знак, чтобы услышать его и увидеть подсказку.</p></div><span class="course-badge">46 базовых знаков</span></div><div class="alphabet-layout"><section class="surface alphabet-surface"><div class="alphabet-head"><h2>Хирагана · ひらがな</h2><span>а　и　у　э　о</span></div><div class="kana-table">${LESSONS.map(l=>`<div class="kana-table-row"><span class="row-label">${l.label}</span><div class="kana-row">${l.ids.map(id=>{const k=BY_ID[id],m=state.mastery[id];return `<button data-action="kana" data-id="${id}" class="kana-tile ${(m?.streak||0)>=3?'mastered':m?'seen':''}" aria-label="${k.char}, ${k.ru}, послушать"><span lang="ja">${k.char}</span><small>${id}</small><i></i></button>`;}).join('')}</div></div>`).join('')}</div><div class="legend"><span><i class="dot"></i>Не изучен</span><span><i class="dot seen"></i>Знакомый знак</span><span><i class="dot mastered"></i>Закреплён</span></div></section><aside class="alphabet-note surface"><span class="big-serif" lang="ja">あ</span><h3>Один знак — одна мора</h3><p>Хирагана записывает звуковые единицы японского языка. Обычно знак соответствует гласному или сочетанию согласного с гласным.</p><p>Русская подсказка передаёт звук приблизительно. За образец бери запись.</p><div class="note-divider"></div><h3>Почему знаки иногда разные?</h3><p>В карточках используется шрифт без засечек. В книгах встречаются и шрифты с засечками. Это те же знаки с тем же чтением.</p><p>Рукописные き и さ тоже могут отличаться от печатных.</p><p class="tiny-note">Звонкие согласные, маленькая っ и сочетания вроде きゃ — следующий этап после базовых знаков.</p></aside></div>`);}
function progress(){const s=stats(state);const badges=[{icon:'sprout',title:'Первый урок',text:'Пройти первый урок',done:state.completed.length>0},{icon:'fire',title:'3 дня подряд',text:'Заниматься 3 дня подряд',done:s.streak>=3},{icon:'star',title:'100 XP',text:'Получить 100 XP',done:state.xp>=100},{icon:'book',title:'10 уроков',text:'Пройти все 10 уроков',done:state.completed.length===10}];return shell(`<div class="page-heading"><div><h1>Прогресс</h1><p>Результаты, ошибки и сохранение.</p></div><span class="course-badge">Уровень ${s.level}</span></div><div class="stat-grid"><div class="surface stat-card">${icon('star')}<strong>${state.xp}<small> XP</small></strong><span>опыта накоплено</span></div><div class="surface stat-card">${icon('grid')}<strong>${s.seen}<small> / 46</small></strong><span>знаков встречено</span></div><div class="surface stat-card">${icon('check')}<strong>${s.accuracy}<small>%</small></strong><span>верных ответов за всё время</span></div><div class="surface stat-card">${icon('fire')}<strong>${s.streak}</strong><span>дней подряд</span></div></div><section class="surface progress-panel"><div class="section-heading"><h2>Достижения</h2><span class="muted">${badges.filter(b=>b.done).length} / 4</span></div><div class="badges">${badges.map(b=>`<div class="badge-card ${b.done?'earned':''}"><span>${icon(b.icon)}</span><strong>${b.title}</strong><small>${b.text}</small></div>`).join('')}</div></section><div class="progress-columns"><section class="surface progress-panel"><h2>Ошибки</h2>${state.mistakes.length?`<div class="mistake-chips">${state.mistakes.map(id=>`<button data-action="kana" data-id="${id}" lang="ja">${BY_ID[id].char}<small>${id}</small></button>`).join('')}</div><button class="primary" data-action="start" data-id="mistakes">Повторить ошибки ${icon('repeat')}</button>`:'<p class="muted">Нет ошибок для повторения.</p>'}</section><section class="surface progress-panel"><h2>Сохранение</h2><p>Прогресс хранится в этом браузере. Для переноса между устройствами подключи синхронизацию. Файл можно использовать как резервную копию.</p><div class="backup-buttons"><button class="secondary" data-action="cloud-open">${icon('cloud')} Синхронизация</button><button class="secondary" data-action="export">${icon('download')} Сохранить файл</button><button class="text-button" data-action="import">${icon('upload')} Загрузить прогресс</button></div><p class="tiny-note">Очистка данных браузера удалит местное сохранение. Файл поможет его восстановить.</p><button class="danger-link" data-action="reset">Начать заново</button></section></div><section class="surface progress-panel"><h2>Последние занятия</h2>${state.history.length?`<div class="history-list">${state.history.slice(0,6).map(h=>`<div><span>${esc(LESSONS.find(l=>l.id===h.lessonId)?.label||(h.lessonId==='mistakes'?'Повторение ошибок':'Повторение'))}</span><span class="muted">${esc(h.date.split('-').reverse().join('.'))} · ${h.correct}/${h.total} с первой попытки</span></div>`).join('')}</div>`:'<p class="muted">Завершённых занятий пока нет.</p>'}</section>`);}
function sources(){return shell(`<div class="page-heading"><div><h1>Источники</h1><p>Irodori, Marugoto, Tae Kim и Genki I.</p></div></div><div class="sources-layout"><section class="surface progress-panel"><h2>Основа учебного модуля</h2><p>Для хираганы использованы открытые материалы Irodori, Marugoto Plus и Tae Kim. Genki 1 — глава 1 второго издания Genki I, стр. 38–57, из твоего комплекта. Формулировки заданий, объяснения и механизм повторения подготовлены для «Каны».</p>${SOURCES.map(s=>`<a class="source-link" href="${s.url}" target="_blank" rel="noopener noreferrer"><span><small>${s.organization}</small><strong>${s.title}</strong><p>${s.use}</p></span>${icon('arrow')}</a>`).join('')}<p class="tiny-note">«Кана» — самостоятельное учебное приложение. Оно не является официальным продуктом авторов этих курсов.</p></section><aside class="surface progress-panel"><span class="source-audio-icon">${icon('speaker')}</span><h2>Про озвучку</h2><p>Для всех 46 знаков хираганы используются записи Marugoto от Japan Foundation. Громкость выровнена. Кнопка «Медленно» воспроизводит ту же запись на скорости 0,8× с сохранением высоты голоса. Отдельные слова пока озвучены голосом Kyoko. Диалоги, полный словарь и упражнения на числа и часы в Genki — оригинальные записи из твоего комплекта. Все записи воспроизводятся прямо в браузере.</p><p class="tiny-note">Source: The Japan Foundation, Japanese-Language Institute, Kansai. <a href="https://a1.marugotoweb.jp/en/hiragana.php" target="_blank" rel="noopener noreferrer">Записи хираганы Marugoto</a>.</p><p>Транскрипция на русском — приблизительная подсказка. Слушай и повторяй за записью.</p><button class="secondary" data-action="play" data-id="a">${icon('speaker')} Послушать пример</button><div class="note-divider"></div><h3>Как работает закрепление</h3><p>Знак считается закреплённым после трёх верных ответов подряд. Это ориентир для практики: уверенное чтение появится с возвращением к знакам в разные дни.</p></aside></div>`);}
function lesson(){const s=state.session;if(!s){view='home';return home();}const l=LESSONS.find(x=>x.id===s.lessonId);const title=sessionTitle(s.lessonId);let body='';
 if(s.phase==='learn'){const k=BY_ID[s.ids[s.learnIndex]];body=`<section class="learning-content"><span class="eyebrow">ЗНАК ${s.learnIndex+1} ИЗ ${s.ids.length}</span><h1>${title}</h1><p class="question-subtitle">Послушай звук и повтори его вслух.</p><div class="learn-card"><span class="learn-kana" lang="ja">${k.char}</span><div class="reading-label"><strong>${k.id}</strong><span>примерно «${k.ru}»</span></div><div class="kana-audio-controls"><button class="audio-button" data-action="play" data-id="${k.id}">${icon('speaker')} Послушать</button><button class="audio-button audio-slow" data-action="play" data-id="${k.id}" data-slow="true">Медленно</button></div><p class="audio-source-note">Запись Marugoto · Japan Foundation</p><p class="pronunciation-hint">${k.hint}</p></div><div class="learn-dots">${s.ids.map((id,i)=>`<button data-action="learn-jump" data-index="${i}" class="${i===s.learnIndex?'selected':''}" aria-label="Знак ${BY_ID[id].char}">${BY_ID[id].char}</button>`).join('')}</div><p class="learning-note">Чтение латиницей пригодится в упражнениях.<br>Можно отвечать и русскими буквами.</p><button class="primary wide" data-action="learn-next">${s.learnIndex===s.ids.length-1?'К упражнениям':'Следующий знак'}${icon('arrow')}</button><button class="text-button learn-skip" data-action="learn-skip">Сразу к упражнениям</button></section>`;}
 else if(s.phase==='result'){const percent=s.firstAnswers?Math.round(s.firstCorrect/s.firstAnswers*100):0;body=`<section class="result-content"><h1>${l?'Урок завершён':'Повторение завершено'}</h1><div class="result-stats"><div><strong>${s.firstCorrect}<small> / ${s.firstAnswers}</small></strong><span>с первой попытки</span></div><div><strong>${percent}<small>%</small></strong><span>точность в занятии</span></div><div><strong>${s.bonus?'+20':stats(state).seen}</strong><span>${s.bonus?'XP за новый урок':'знаков уже знакомо'}</span></div></div>${l?`<div class="word-discovery"><span class="eyebrow">ПРИМЕР СЛОВА</span><strong lang="ja">${l.word[0]}</strong><span>${l.word[1]} · ${l.word[2]}</span><button class="icon-button" data-action="play" data-id="word-${l.id}" aria-label="Послушать слово ${l.word[2]}">${icon('speaker')}</button></div>`:''}${state.mistakes.length?`<p class="result-note">Осталось ошибок: ${state.mistakes.length}.</p>`:''}<button class="primary wide" data-action="finish">К урокам ${icon('arrow')}</button><button class="text-button" data-action="repeat-lesson" data-id="${s.lessonId}">Повторить урок</button></section>`;}
 else{const q=s.questions[s.index],k=BY_ID[q.id],f=s.feedback;const prompt=q.type==='read'?'Как читается этот знак?':q.type==='listen'?'Какой знак ты слышишь?':'Напиши чтение знака';body=`<section class="exercise-content"><div class="exercise-meta"><span class="eyebrow">${q.retry?'ПОВТОР ОШИБКИ':q.type==='listen'?'НА СЛУХ':q.type==='type'?'ВВОД ЧТЕНИЯ':'ЧТЕНИЕ'}</span><span class="muted">${s.index+1} / ${s.questions.length}</span></div><h1>${prompt}</h1><p class="question-subtitle">${q.type==='type'?'Латиницей или русскими буквами.':q.type==='listen'?'Нажми на динамик и выбери ответ.':'Выбери подходящее чтение.'}</p>${q.type==='listen'?`<button class="listening-orb" data-action="play" data-id="${q.id}" aria-label="Послушать задание">${icon('speaker')}<span>Послушать ещё</span></button><button class="text-button listen-slow" data-action="play" data-id="${q.id}" data-slow="true">Послушать медленно</button>`:`<div class="exercise-kana" lang="ja">${k.char}<button class="icon-button" data-action="play" data-id="${k.id}" aria-label="Послушать знак">${icon('speaker')}</button></div>`}${q.type==='type'?`<form id="answer-form"><label class="sr-only" for="reading">Чтение знака</label><input id="reading" name="reading" class="reading-input ${f?(f.correct?'input-correct':'input-wrong'):''}" placeholder="Твой ответ" autocomplete="off" autocapitalize="none" spellcheck="false" ${f?'disabled':''} value="${f?esc(f.value):''}"><button class="primary wide" type="submit" ${f?'disabled':''}>Проверить ${icon('check')}</button></form>`:`<div class="answer-grid">${q.options.map((id,i)=>`<button class="answer-option ${f?(id===q.id?'answer-correct':id===f.value?'answer-wrong':'answer-muted'):''}" data-action="answer" data-id="${id}" ${f?'disabled':''}><span class="option-key">${i+1}</span><span class="${q.type==='listen'?'option-kana':''}" ${q.type==='listen'?'lang="ja"':''}>${q.type==='listen'?BY_ID[id].char:id}</span>${f&&id===q.id?icon('check'):f&&id===f.value?icon('close'):''}</button>`).join('')}</div>`}<div class="exercise-feedback ${f?(f.correct?'is-correct':'is-wrong'):''}" ${f?'role="status" aria-live="polite"':''}>${f?`<div class="feedback-main"><span class="feedback-icon">${icon(f.correct?'check':'repeat')}</span><div><strong>${f.correct?'Верно':'Ошибка'}</strong><p>${f.correct?`${k.char} читается ${k.id}${f.earned?` · +${f.earned} XP`:''}`:`${k.char} → ${k.id} · примерно «${k.ru}». Повторится в этом уроке.`}</p></div></div>${!f.correct?`<p class="feedback-hint">${k.hint}</p>`:''}<button class="primary wide" data-action="next">Продолжить ${icon('arrow')}</button>`:''}</div></section>`;}
 const fraction=s.phase==='learn'?(s.learnIndex/s.ids.length)*10:s.phase==='result'?100:10+(s.index/s.questions.length)*90;
 return `<div class="lesson-shell"><header class="lesson-top"><button class="exit-button" data-action="exit" aria-label="Выйти из занятия, сохранив прогресс">${icon('close')}</button><div class="lesson-top-center"><span>${title}</span><div class="session-track" role="progressbar" aria-label="Ход занятия" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(fraction)}"><span style="width:${fraction}%"></span></div></div><span class="session-xp">${icon('star')}${state.xp}</span></header><main id="main" tabindex="-1" class="lesson-main">${body}</main>${autosaveMarkup()}</div>`;}

function autosaveMarkup(){const c=cloud?.snapshot(),labels={synced:'Сохранено в облаке',syncing:'Сохраняется…',pending:'Сохраняется…',offline:'На устройстве · отправится при подключении',error:'Сохранено на устройстве · ошибка отправки','auth-required':'Нужен вход для сохранения',conflict:'Нужно выбрать версию',disconnected:'Сохранено на устройстве'};return `<button class="autosave-line ${c?.status||''}" data-autosave data-action="cloud-open" aria-live="polite">${icon('cloud')}<span>${labels[c?.status]||'Сохранено на устройстве'}</span></button>`;}
function practicePage(){const known=learnedKana(state),s=stats(state),nextDue=Math.min(...Object.values(state.mastery).map(m=>m.dueAt).filter(t=>t>Date.now()));return shell(`<div class="page-heading"><div><h1>Закрепление хираганы</h1><p>Повторяй знакомые знаки в любое время.</p></div></div><section class="surface progress-panel"><h2>Все изученные знаки</h2><p>${known.length?`${known.length} знаков. Чтение, задания на слух и ввод ответа. Ошибки и менее уверенные знаки встретятся чаще.`:'После первых ответов здесь появятся знакомые знаки.'}</p><button class="primary" data-action="start" data-id="practice" ${!known.length?'disabled':''}>Закрепить изученное</button></section><div class="review-actions"><button class="secondary" data-action="start" data-id="mistakes" ${!state.mistakes.length?'disabled':''}>Ошибки · ${state.mistakes.length}</button><button class="secondary" data-action="start" data-id="review" ${!s.due?'disabled':''}>По расписанию · ${s.due}</button></div>${!s.due&&Number.isFinite(nextDue)?`<p class="tiny-note">Ближайшее интервальное повторение: ${new Date(nextDue).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}. Закрепление доступно уже сейчас.</p>`:''}<button class="genki-course-card dungeon-course-card" data-action="nav" data-view="dungeon"><span><strong>Подземелье хираганы</strong><small>${state.dungeon.run?.status==='explore'?'Продолжить · этаж '+state.dungeon.run.floor+'/3':'3 этажа · монстры-знаки · ввод чтения'}</small></span><span>@ ${icon('chevron')}</span></button><section class="compact-lessons"><div class="section-heading"><h2>По рядам</h2></div><div class="lesson-list">${LESSONS.map(l=>{const ids=l.ids.filter(id=>known.includes(id));return `<button class="lesson-card" data-action="start" data-id="practice:${l.id}" ${!ids.length?'disabled':''}><span class="lesson-symbol" lang="ja">${BY_ID[l.ids[0]].char}</span><span class="lesson-card-copy"><strong>${l.label}</strong><span class="kana-preview" lang="ja">${ids.length?ids.map(id=>BY_ID[id].char).join('　'):'—'}</span><small>${ids.length} / ${l.ids.length} знакомых знаков</small></span></button>`;}).join('')}</div></section>`);}
function beginGenki(id){const run=()=>{const session=startGenki(id,state.genki);if(!session){toast('Сначала выполни задания Genki.');return;}state={...state,activeCourse:'genki',genki:{...state.genki,session}};genkiDraft=[];save();navigate('genki-lesson');};const old=state.genki.session;if(old&&old.phase!=='result'){if(old.unitId===id){state.activeCourse='genki';save();navigate('genki-lesson');return;}showDialog('Начать другое занятие?','Результаты ответов сохранены. Текущее занятие Genki будет заменено новым.',run,'Начать');}else run();}
function beginDungeon(mode){const run=()=>{const next=startDungeon(state,mode);if(next===state){toast('Сначала изучи знаки или выбери ряд.');return;}state=next;save();navigate('dungeon-run');};if(state.dungeon.run?.status==='explore')showDialog('Начать новый забег?','Текущий забег будет заменён. Результаты ответов и ошибки сохранятся.',run,'Начать');else run();}
function dungeonUpdate(next,focus=false){if(next===state)return;state=next;save();render();if(focus)document.querySelector('#dungeon-reading')?.focus({preventScroll:true});}
function submitDungeon(value){const next=attackDungeon(state,value);if(next===state)return;dungeonUpdate(next);const feedback=state.dungeon.run.feedback;if(feedback)play(feedback.kana);document.querySelector('[data-action="dungeon-next"]')?.focus({preventScroll:true});}
function submitGenki(value){if(!String(value).trim())return;state=answerGenki(state,value);save();render();document.querySelector('.exercise-feedback')?.scrollIntoView({block:'nearest',behavior:'smooth'});document.querySelector('[data-action="genki-next"]')?.focus({preventScroll:true});}
async function playGenki(id){if(!Object.hasOwn(GENKI_AUDIO,id))return;if(audio)audio.pause();playingId=null;updateSoundButtons();audio=new Audio(GENKI_AUDIO[id]);try{await audio.play();}catch{toast('Запись недоступна. Проверь соединение.',true);}}
async function logout(){await cloud.sync();try{const response=await fetch('/auth/logout',{method:'POST',credentials:'same-origin'});if(!response.ok)throw new Error();cloud.disconnect();if('serviceWorker'in navigator)for(const registration of await navigator.serviceWorker.getRegistrations())await registration.unregister();if('caches'in window)for(const key of await caches.keys())if(key.startsWith('kana:'))await caches.delete(key);location.assign('/');}catch{toast('Для выхода подключись к интернету.',true);}}

const cloudLabels={disconnected:'Не подключено','auth-required':PRIVATE_APP?'Нужен вход':'Неверный ключ',syncing:'Синхронизация',synced:'Сохранено',pending:'Сохраняется',offline:'Нет соединения',error:'Ошибка',conflict:'Конфликт версий'};
function cloudIndicator(){const c=cloud?.snapshot();return `<button id="cloud-indicator" class="cloud-indicator ${c?.status||'disconnected'}" data-action="cloud-open" aria-label="Синхронизация: ${cloudLabels[c?.status]||'Не подключено'}" title="Синхронизация: ${cloudLabels[c?.status]||'Не подключено'}">${icon('cloud')}<i></i></button>`;}
function cloudWidget(){
 const c=cloud.snapshot(),busy=c.status==='syncing';
 const descriptions={disconnected:'Подключи это устройство по ключу синхронизации.','auth-required':PRIVATE_APP?'Войди снова, чтобы продолжить автосохранение.':'Ключ не подходит. Проверь файл подключения.',syncing:'Проверка и сохранение прогресса.',synced:'Все изменения сохранены в облаке.',pending:'Ответ и текущий шаг отправляются в облако.',offline:'Прогресс сохранён локально. Отправится после подключения к сети.',error:c.error||'Синхронизация не выполнена.',conflict:'На устройствах есть разные версии. Выбери, какую продолжить.'};
 return `<section class="surface progress-panel cloud-panel" data-cloud-panel><div class="cloud-panel-heading"><h2>Автосохранение</h2><span class="sync-status ${c.status}">${cloudLabels[c.status]}</span></div><p>${esc(descriptions[c.status]||'')}</p><div class="cloud-controls">${c.status==='conflict'?'<button class="primary" data-action="cloud-conflict">Выбрать версию</button>':c.configured&&c.status!=='auth-required'?`<button class="primary" data-action="cloud-sync" ${busy?'disabled':''}>${icon('repeat')} Синхронизировать</button>`:`<button class="primary" data-action="cloud-config">${c.status==='auth-required'?(PRIVATE_APP?'Войти':'Изменить ключ'):'Подключить устройство'}</button>`}${c.hasKey?'<button class="text-button" data-action="cloud-disconnect">Отключить</button>':''}${c.configured&&!PRIVATE_APP?'<button class="text-button" data-action="cloud-config">Настройка</button>':''}</div>${c.lastSavedAt?`<p class="tiny-note">Последняя запись: ${new Date(c.lastSavedAt).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}</p>`:''}</section>`;
}
function refreshCloudUI(){if(!cloud)return;document.querySelectorAll('[data-autosave]').forEach(el=>el.outerHTML=autosaveMarkup());const panel=document.querySelector('[data-cloud-panel]');if(panel)panel.outerHTML=cloudWidget();const indicator=document.querySelector('#cloud-indicator');if(indicator)indicator.outerHTML=cloudIndicator();}
function cloudPage(){return shell(`<div class="page-heading"><div><h1>Сохранение</h1><p>Ответы и текущие занятия сохраняются автоматически.</p></div></div>${cloudWidget()}<section class="surface progress-panel"><h2>Другие устройства</h2><p>Открой приложение и войди с тем же ключом. Прогресс загрузится из облака.</p><p>Без сети ответы остаются на устройстве. Приложение отправит их при восстановлении соединения. Если версии разошлись, можно выбрать нужную.</p><div class="cloud-help"><a href="privacy.html" target="_blank" rel="noopener noreferrer">Данные и доступ</a>${PRIVATE_APP?'<button class="text-button" data-action="logout">Выйти на этом устройстве</button>':''}</div></section>`);}

function cloudConfig(){
 if(PRIVATE_APP){location.assign('/');return;}
 const dialog=document.querySelector('#dialog'),c=cloud.snapshot();
 dialog.innerHTML=`<div class="dialog-inner cloud-config"><button class="dialog-close icon-button" id="dialog-cancel" aria-label="Закрыть">${icon('close')}</button><h2>Подключить устройство</h2><form id="cloud-config"><label for="sync-endpoint">Адрес синхронизации</label><input id="sync-endpoint" class="reading-input" name="endpoint" type="url" autocomplete="url" placeholder="https://jap-learn-sync.…workers.dev" value="${esc(c.endpoint)}" required><label for="sync-key">Ключ синхронизации</label><input id="sync-key" class="reading-input" name="key" type="password" autocomplete="off" spellcheck="false" placeholder="${c.hasKey?'Сохранён — можно оставить пустым':'Из файла подключения'}" ${c.hasKey?'':'required'}><p class="tiny-note">Ключ сохранится в браузере этого устройства.</p><button type="submit" class="primary wide">Сохранить и подключить</button></form><a class="setup-link" href="sync-setup.html" target="_blank" rel="noopener noreferrer">Инструкция подключения</a></div>`;
 dialog.querySelector('#dialog-cancel').onclick=()=>dialog.close();dialog.showModal();
}
function cloudConflict(){
 const c=cloud.snapshot();if(!c.conflict)return;const dialog=document.querySelector('#dialog');
 const card=(id,label,st,date)=>`<button class="conflict-choice" data-action="cloud-choose" data-id="${esc(id)}"><strong>${esc(label)}</strong><span>${st.completed.length}/10 хирагана · ${st.genki?.completed?.length||0}/7 Genki · ${st.xp} XP · ${st.answered} ответов</span>${date?`<small>${new Date(date).toLocaleString('ru-RU')}</small>`:''}</button>`;
 dialog.innerHTML=`<div class="dialog-inner"><h2>Какой прогресс продолжить?</h2><p>Выбранная версия станет текущей на всех устройствах. История сохранений останется на сервере.</p>${card('local','Это устройство',state)}${c.conflict.heads.map((h,i)=>card(h.id,`Cloudflare${c.conflict.heads.length>1?' · версия '+(i+1):''}`,h.state,h.savedAt)).join('')}<button class="text-button" id="dialog-cancel">Отмена</button></div>`;
 dialog.querySelector('#dialog-cancel').onclick=()=>dialog.close();dialog.showModal();
}
function render(){const owner=state.genki.session?`${state.genki.session.startedAt}:${state.genki.session.index}`:'';if(owner!==genkiDraftOwner){genkiDraft=[];genkiDraftOwner=owner;}app.innerHTML=view==='dungeon-run'?dungeonRun(state,autosaveMarkup()):view==='dungeon'?shell(dungeonHome(state)):view==='genki-lesson'?genkiLesson(state,{syncMarkup:autosaveMarkup(),draft:genkiDraft}):view==='genki'?shell(genkiHome(state)):view==='practice'?practicePage():view==='lesson'?lesson():view==='alphabet'?alphabet():view==='progress'?progress():view==='sources'?sources():view==='sync'?cloudPage():home();updateSoundButtons();refreshCloudUI();}
function navigate(target){if(audio){audio.pause();playingId=null;}view=target;render();window.scrollTo({top:0,behavior:'instant'});}
function begin(id){if(state.session&&!state.session.finished){if(state.session.lessonId===id){navigate('lesson');return;}showDialog('Продолжить новое занятие?','Прогресс ответов сохранён. Незаконченный урок будет заменён новым.',()=>doBegin(id),'Начать новое');return;}doBegin(id);}
function doBegin(id){const s=startSession(id,state);if(!s){toast('Нет знаков для повторения.');return;}state={...state,session:s,activeCourse:'kana'};save();navigate('lesson');}
function updateSoundButtons(){document.querySelectorAll('[data-action="play"]').forEach(b=>b.classList.toggle('playing',kanaAudioURL(b.dataset.id,b.dataset.slow==='true')===playingId));}
async function play(id,slow=false){const src=kanaAudioURL(id,slow);if(!src)return;if(audio){audio.pause();audio.currentTime=0;}const current=new Audio(src);audio=current;playingId=src;updateSoundButtons();current.onended=()=>{if(audio!==current)return;playingId=null;updateSoundButtons();};try{await current.play();}catch(error){if(audio!==current)return;playingId=null;updateSoundButtons();toast('Не получилось включить запись. Проверь соединение и нажми ещё раз.',true);}}
function showDialog(title,text,confirm,label='Продолжить'){const dialog=document.querySelector('#dialog');dialog.innerHTML=`<div class="dialog-inner"><span class="dialog-icon">${icon('info')}</span><h2>${esc(title)}</h2><p>${esc(text)}</p><button class="primary wide" id="dialog-confirm">${label}</button><button class="text-button" id="dialog-cancel">Отмена</button></div>`;dialog.querySelector('#dialog-confirm').onclick=()=>{dialog.close();confirm();};dialog.querySelector('#dialog-cancel').onclick=()=>dialog.close();dialog.showModal();}
function kanaModal(id){const k=BY_ID[id],dialog=document.querySelector('#dialog');dialog.innerHTML=`<div class="dialog-inner kana-dialog"><button class="dialog-close icon-button" id="dialog-cancel" aria-label="Закрыть">${icon('close')}</button><span class="learn-kana" lang="ja">${k.char}</span><div class="reading-label"><strong>${k.id}</strong><span>примерно «${k.ru}»</span></div><p>${k.hint}</p><div class="kana-audio-controls"><button class="audio-button" data-action="play" data-id="${id}">${icon('speaker')} Послушать ещё</button><button class="audio-button audio-slow" data-action="play" data-id="${id}" data-slow="true">Медленно</button></div><p class="audio-source-note">Запись Marugoto · Japan Foundation</p></div>`;dialog.querySelector('#dialog-cancel').onclick=()=>dialog.close();dialog.showModal();play(id);}
function submitAnswer(value){if(!value.trim())return;state=answer(state,value);save();render();if(state.session?.feedback){document.querySelector('.exercise-feedback').scrollIntoView({block:'nearest',behavior:'smooth'});document.querySelector('[data-action="next"]')?.focus({preventScroll:true});}}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const {action,id}=b.dataset;
 switch(action){case 'nav':navigate(b.dataset.view);break;case 'logout':logout();break;case 'dungeon-resume':state.activeCourse='dungeon';save();navigate('dungeon-run');break;case 'dungeon-exit':navigate('dungeon');cloud.sync();break;case 'dungeon-again':beginDungeon(state.dungeon.run.mode);break;case 'dungeon-target':dungeonUpdate(selectMonster(state,Number(id)),true);break;case 'dungeon-move':dungeonUpdate(moveDungeon(state,id));break;case 'dungeon-descend':dungeonUpdate(descendDungeon(state));break;case 'dungeon-hint':{dungeonUpdate(hintDungeon(state));const f=state.dungeon.run.feedback;if(f)play(f.kana);break;}case 'dungeon-next':dungeonUpdate(continueDungeon(state),true);break;case 'genki-start':beginGenki(id);break;case 'genki-resume':state.activeCourse='genki';save();navigate('genki-lesson');break;case 'genki-exit':navigate('genki');cloud.sync();break;case 'genki-play':playGenki(id);break;case 'genki-learn-next':{const gs=state.genki.session,u=GENKI_UNIT_BY_ID[gs.unitId];if(gs.cardIndex+1<u.cards.length)gs.cardIndex++;else gs.phase='exercise';save();render();window.scrollTo({top:0,behavior:'instant'});break;}case 'genki-skip':state.genki.session.phase='exercise';save();render();window.scrollTo({top:0,behavior:'instant'});break;case 'genki-answer':submitGenki(b.dataset.value);break;case 'genki-token':{const i=Number(b.dataset.index),q=GENKI_QUESTION_BY_ID[state.genki.session.questions[state.genki.session.index].id];if(Number.isInteger(i)&&i>=0&&i<q.tokens.length&&!genkiDraft.includes(i))genkiDraft.push(i);render();break;}case 'genki-undo':genkiDraft.pop();render();break;case 'genki-build-check':{const q=GENKI_QUESTION_BY_ID[state.genki.session.questions[state.genki.session.index].id];submitGenki(genkiDraft.map(i=>q.tokens[i]).join(''));break;}case 'genki-next':state=advanceGenki(state);save();render();window.scrollTo({top:0,behavior:'instant'});break;case 'genki-finish':state.genki.session=null;save();navigate('genki');break;case 'genki-repeat':state.genki.session=null;beginGenki(id);break;case 'cloud-open':navigate('sync');break;case 'cloud-config':cloudConfig();break;case 'cloud-connect':if(!cloud.snapshot().configured){cloudConfig();break;}cloud.connect().catch(e=>toast(e.message,true));break;case 'cloud-sync':cloud.sync();break;case 'cloud-disconnect':cloud.disconnect();break;case 'cloud-conflict':cloudConflict();break;case 'cloud-choose':document.querySelector('#dialog').close();cloud.resolveConflict(id).catch(e=>toast(e.message,true));break;case 'start':begin(id);break;case 'resume':state.activeCourse='kana';save();navigate('lesson');break;case 'play':play(id,b.dataset.slow==='true');break;case 'kana':kanaModal(id);break;case 'learn-jump':state.session.learnIndex=Number(b.dataset.index);save();render();break;case 'learn-skip':state.session.phase='exercise';save();render();window.scrollTo({top:0,behavior:'instant'});break;case 'learn-next':if(state.session.learnIndex<state.session.ids.length-1)state.session.learnIndex++;else state.session.phase='exercise';save();render();window.scrollTo({top:0,behavior:'instant'});break;case 'answer':submitAnswer(id);break;case 'next':state=advance(state);save();render();window.scrollTo({top:0,behavior:'instant'});break;case 'exit':navigate('home');cloud.sync();toast('Занятие сохранено.');break;case 'finish':state.session=null;save();navigate('home');break;case 'repeat-lesson':state.session=null;doBegin(id);break;case 'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`kana-garden-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Файл прогресса подготовлен.');break;}case 'import':{const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{if(!input.files[0])return;if(input.files[0].size>2e6)throw new Error('Файл слишком большой.');const imported=validateState(JSON.parse(await input.files[0].text()));showDialog('Восстановить прогресс из файла?','Текущее сохранение в этом браузере будет заменено данными из файла.',()=>{state=imported;save();navigate('progress');toast('Прогресс восстановлен.');},'Восстановить');}catch(error){toast(error.message||'Не удалось прочитать файл.',true);}};input.click();break;}case 'reset':showDialog('Сбросить прогресс?','Опыт, история и результаты в этом браузере будут удалены. Перед этим можно выгрузить файл прогресса.',()=>{state=freshState();save();navigate('home');toast('Прогресс сброшен.');},'Начать заново');break;}
});
document.addEventListener('submit',async event=>{if(event.target.id==='dungeon-start-form'){event.preventDefault();beginDungeon(String(new FormData(event.target).get('mode')||'learned'));return;}if(event.target.id==='dungeon-answer-form'){event.preventDefault();submitDungeon(String(new FormData(event.target).get('reading')||''));return;}if(event.target.id==='genki-answer-form'){event.preventDefault();submitGenki(String(new FormData(event.target).get('reading')||''));return;}if(event.target.id==='cloud-config'){event.preventDefault();const button=event.target.querySelector('button[type=submit]'),data=new FormData(event.target);button.disabled=true;try{await cloud.configure(String(data.get('endpoint')||'').trim(),String(data.get('key')||'').trim());document.querySelector('#dialog').close();if(cloud.snapshot().status==='synced')toast('Устройство подключено.');}catch(e){button.disabled=false;toast(e.message,true);}return;}if(event.target.id!=='answer-form')return;event.preventDefault();submitAnswer(new FormData(event.target).get('reading')||'');});
document.addEventListener('keydown',event=>{if(view==='dungeon-run'&&!document.querySelector('#dialog').open&&!event.repeat){if(['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName))return;const direction={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right','.':'wait'}[event.key];if(direction){event.preventDefault();dungeonUpdate(moveDungeon(state,direction));return;}if(event.key==='Enter'&&state.dungeon.run.feedback){event.preventDefault();dungeonUpdate(continueDungeon(state),true);return;}}if(view!=='lesson'||document.querySelector('#dialog').open||event.repeat)return;const tag=event.target.tagName;if(['INPUT','TEXTAREA'].includes(tag))return;const s=state.session;if(s?.phase!=='exercise')return;if(event.key==='Enter'&&s.feedback){event.preventDefault();document.querySelector('[data-action="next"]')?.click();}else if(/^[1-4]$/.test(event.key)&&!s.feedback){const q=s.questions[s.index];if(q.type!=='type'){event.preventDefault();submitAnswer(q.options[Number(event.key)-1]);}}});
window.addEventListener('storage',event=>{if(event.key!==STORAGE_KEY||!event.newValue)return;try{state=validateState(JSON.parse(event.newValue));render();cloud?.noteChange();toast('Прогресс обновлён из другой вкладки.');}catch(error){}});
cloud=createCloudSync({getState:()=>state,applyState:remote=>{state=validateState(JSON.parse(JSON.stringify(remote)));save(false);navigate(location.hash==='#dungeon'?'dungeon':'home');},onStatus:refreshCloudUI,onMessage:toast,sessionAuth:PRIVATE_APP,endpointOverride:PRIVATE_APP?location.origin:''});
render();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
